import {mount,esc,money,pct,options,allocation,revisionForm,versionSelect,delta,methodDetails,limits} from '../shared/experience.js';
const action=(label,a,extra='',cls='action')=>`<button class="${cls}" data-action="${a}" ${extra}>${label}</button>`;
const loss=(o,k)=>o?.losses?.[k] ==null?'—':money(o.losses[k]);
const badge=o=>o.reference?'Référence indépendante':o.admissible?'Dans les contraintes':'Hors contraintes';
const optical=`<div class="optical" aria-hidden="true"><div class="thermal"></div><div class="flutes"></div><div class="caustic"></div><div class="refraction"></div></div>`;
function header(s){return `<header class="masthead"><a class="brand" href="../index.html" aria-label="AlphaForge, les trois directions"><span class="brand-mark" aria-hidden="true"></span>AlphaForge<span>.</span></a><div class="direction"><b>03</b> PRISME <span>Un autre regard sur la décision</span></div><a class="gallery" href="../index.html">Comparer les directions <span aria-hidden="true">↗</span></a></header><div class="context-bar"><div><span class="status-point"></span><strong>Robert</strong><span>Réserve et retrait</span><small>${s.local?'Copie calculée localement · aucun agent relancé':'Résultats archivés · aucun nouvel appel AWS'}</small></div><div class="context-controls">${versionSelect(s)}<div class="level" role="group" aria-label="Profondeur de lecture">${action('Voir clair','level','data-level="accessible" aria-pressed="'+(s.level==='accessible')+'"','level-button')}${action('Voir au-delà','level','data-level="deep" aria-pressed="'+(s.level==='deep')+'"','level-button')}</div></div></div>`}
function nav(s){return `<nav class="view-nav" aria-label="Dans le dossier">${[['overview','01','Comprendre'],['compare','02','Mettre côte à côte'],['revise','03','Faire évoluer']].map(([view,n,t])=>`<button data-action="view" data-view="${view}" aria-current="${s.view===view?'page':'false'}"><span>${n}</span>${t}</button>`).join('')}<div class="nav-tail">Même dossier. Même rigueur.<span>Le niveau de lecture ne change pas les résultats.</span></div></nav>`}
function unresolved(s){const a=s.v.analysis||{}, c=(a.checks||[]).find(c=>c.certified&&c.id==='reserve_budget_contradiction');return `<section class="no-solution"><p class="eyebrow">${a.status==='infeasible'?'Une contradiction établie':'Une analyse incomplète'}</p><h1>Le calcul s’arrête.<br>La décision continue.</h1><p>${c?`Le retrait de <strong>${money(c.withdrawal_cad)} CAD</strong> dépasse le capital déclaré de <strong>${money(c.capital_cad)} CAD</strong>. Il manque ${money(c.shortfall_cad)} CAD. Financer toute la réserve dès le départ, sans apport extérieur et à rendement nul, est impossible dans ce modèle.`:'Aucune allocation admissible n’est établie dans ce dossier. Les contrôles expliquent ce qui empêche le calcul ; aucune valeur n’est remplacée par une estimation.'}</p><p class="infeasible-scope">${c?'Certificat algébrique indépendant du solveur. Aucun IIS global ni préférence de réparation n’est déduit.':'La correction doit répondre aux données absentes ou aux contraintes contradictoires.'}</p><div class="hero-actions">${action('Corriger une hypothèse','view','data-view="revise"','action dark')}${action('Examiner les contrôles','proof','data-proof="method"','action')}${action('Revenir à l’état précédent','undo','','text-action')}</div>${s.previous?`<div class="compare-delta">${delta(s)}</div>`:''}</section>`}
const assetLabels={RESERVE_ABSTRAITE:'Réserve abstraite',TSLA:'TSLA','XBB.TO':'XBB','XIU.TO':'XIU','ZST.TO':'ZST'};
function overview(s){const p=s.v.problem,m=s.v.stats.min_reallocation_cad,multiple=s.v.analysis?.optimal_face?.non_unique_witness_found,os=options(s),chosen=os.find(o=>o.id===s.selected&&o.id!=='baseline')||os.find(o=>o.id==='minimum_turnover'),entries=Object.entries(chosen.weights),nonzero=entries.filter(([,w])=>w>1e-9);return `<section class="capital-room"><div class="room-heading"><p class="eyebrow">Le capital, mis en perspective</p><h1>${multiple?'Le même capital.<br>Plusieurs équilibres.':'Un capital.<br>Un équilibre à examiner.'}</h1><p><strong>${money(m)} CAD à déplacer au minimum.</strong> ${multiple?'Plusieurs allocations atteignent ce minimum conditionnel.':'Aucun témoin de minimum multiple n’a été trouvé.'}</p><p class="room-scope">${s.v.simple_reference?'La règle simple atteint aussi ce minimum. ':''}Deux chocs hypothétiques, aucune probabilité ni garantie du capital.</p></div><div class="capital-instrument"><div class="instrument-header"><div><span>Portefeuille initial fictif</span><strong>${money(p.capital_cad)} CAD</strong></div><div><span>Exigence de retrait</span><strong>${money(p.withdrawal_cad)} CAD · ${p.withdrawal_months} mois</strong></div><div><span>Perte admissible</span><strong>${money(p.scenario_loss_limit_cad)} CAD par choc</strong></div></div><div class="option-rail" role="group" aria-label="Allocation à mettre en lumière">${os.filter(o=>o.id!=='baseline').map(o=>action(esc(o.label),'select',`data-option="${o.id}" aria-pressed="${chosen.id===o.id}"`,'lens-button')).join('')}<span>À examiner · aucune option préférée déduite</span></div><div class="capital-beam" role="img" aria-label="Allocation de ${esc(chosen.label)}. ${entries.map(([a,w])=>esc(assetLabels[a]||a)+' '+pct(w)).join(', ')}">${nonzero.map(([a,w],i)=>`<div class="beam-segment beam-${a==='RESERVE_ABSTRAITE'?'reserve':a==='TSLA'?'tsla':a==='XBB.TO'?'xbb':a==='XIU.TO'?'xiu':'zst'}" style="flex:${w}" aria-hidden="true"><span class="beam-light"></span><span class="beam-name">${esc(assetLabels[a]||a)}</span><span class="beam-value">${pct(w)}</span><span class="beam-baseline"></span></div>`).join('')}</div><div class="capital-readout">${entries.map(([a,w])=>`<div><span>${esc(assetLabels[a]||a)}</span><strong>${money(w*p.capital_cad)} <small>CAD</small></strong><span>${pct(w)} du capital</span></div>`).join('')}</div><div class="instrument-caption"><p>Largeurs proportionnelles aux poids initiaux. La lumière est décorative ; elle ne code aucun risque. TSLA ≤ ${pct(p.max_asset_weights.TSLA)}.</p><span>${esc(chosen.label)} · ${money(chosen.turnover)} CAD déplacés</span></div></div><div class="room-actions">${action('Pourquoi ce minimum ? <span aria-hidden="true">↗</span>','proof','data-proof="minimum_reallocation"','action dark')}${action('Comparer les pertes par choc','view','data-view="compare"','text-action')}${action('Faire évoluer une hypothèse','view','data-view="revise"','text-action')}</div><section class="clear-limit"><span aria-hidden="true">↳</span><div><h2>${s.v.simple_reference?'La règle simple atteint aussi ce minimum.':'Ce minimum ne désigne pas le moins risqué.'}</h2><p>${s.v.simple_reference?'Aucune supériorité des quatre agents n’est établie ici. ':'La référence simple de r5 n’est pas extrapolée à cet état. '}Deux chocs hypothétiques, aucune probabilité ni garantie du capital. Les pertes diffèrent entre allocations.</p></div>${action('Voir les différences','view','data-view="compare"','text-action')}</section></section>`}
function compare(s){const os=options(s),selected=os.find(o=>o.id===s.selected)||os.find(o=>o.id==='minimum_turnover')||os[0];return `<section class="compare-intro"><p class="eyebrow">La table de lumière</p><h1>Un même objectif.<br><span>Des expositions différentes.</span></h1><p>Chaque option repart du même portefeuille initial. Les colonnes alignent les mêmes unités, sans score de préférence inventé.</p></section>${s.previous?`<section class="compare-delta"><h2>Le changement, avant la comparaison.</h2>${delta(s)}</section>`:''}<section class="light-table" aria-label="Comparer les allocations">${os.map((o,i)=>`<article class="option-screen ${selected.id===o.id?'selected':''}"><div class="screen-light" aria-hidden="true"></div><span class="option-index">${String(i+1).padStart(2,'0')}</span><div class="option-name"><h2>${esc(o.label)}</h2><p class="option-state ${o.admissible?'':'outside'}">${badge(o)}</p></div><div class="option-amount"><strong>${money(o.turnover)}</strong><span>CAD à réallouer</span></div><div class="exposure">${allocation(o)}</div><dl class="scenario-values"><div><dt>Choc actions</dt><dd>${loss(o,'actions')} <small>CAD</small></dd></div><div><dt>Choc obligations</dt><dd>${loss(o,'obligations')} <small>CAD</small></dd></div></dl>${action(selected.id===o.id?'Option examinée <span aria-hidden="true">↗</span>':'Examiner cette option <span aria-hidden="true">↗</span>','select',`data-option="${o.id}" aria-pressed="${selected.id===o.id}"`,'select-option')}</article>`).join('')}</section><section class="focus-line"><div><span class="eyebrow">L’option dans son contexte</span><h2>${esc(selected.label)}</h2><p>${selected.admissible?'Respecte les contraintes contrôlées de ce modèle. Cela ne constitue pas une validation de placement réel.':'Ne respecte pas toutes les contraintes actuelles. Elle reste visible comme point de départ, pas comme proposition admissible.'}</p></div>${action('Ouvrir le calcul et ses conditions','proof','data-proof="method"','action')}</section><p class="comparison-foot">Les montants de perte décrivent deux chocs hypothétiques en CAD, à l’échéance. Ni probabilités, ni perte future maximale. Un témoin du solveur n’est pas un optimum de risque.</p>${s.v.simple_reference?`<p class="simple-note"><strong>Point de comparaison décisif.</strong> La règle simple atteint aussi le minimum de ${money(s.v.simple_reference.independent.turnover_cad)} CAD.</p>`:''}`}
function revise(s){const prev=s.previous;return `<section class="revision-intro"><div><p class="eyebrow">Une hypothèse change. Le reste demeure.</p><h1>Déplacer le point<br><span>de vue.</span></h1><p>Essayez une correction dans une copie. Les résultats précédents gardent leur portée ; aucune session du produit n’est modifiée.</p></div><div class="revision-hint">${action('Essayer un retrait de 40 000 CAD','draft','data-withdrawal="40000"','action dark')}<p>Ce raccourci remplit le formulaire.<br>Il ne lance pas le calcul.</p></div></section><section class="revision-stage"><div class="past-state"><p class="eyebrow">${prev?'État précédent':'Point de départ'}</p><div class="revision-number">${money((prev||s.v).stats.min_reallocation_cad)}<small>CAD au minimum</small></div><p>Retrait : ${money((prev||s.v).problem.withdrawal_cad)} CAD<br>Perte admissible par choc : ${money((prev||s.v).problem.scenario_loss_limit_cad)} CAD</p><div class="state-actions">${action('Revenir à l’état précédent','undo','','text-action')}${action('Retrouver Robert initial','reset','','text-action')}</div></div><div class="refractive-divider" aria-hidden="true"></div><div class="next-state"><p class="eyebrow">L’hypothèse à examiner</p>${revisionForm(s)}<p class="runtime-note">Calcul local réel. Une exploration n’est pas une nouvelle revue des quatre agents. Les dépendances sont prévues, pas jouées comme des événements.</p></div></section>${prev?`<section class="revision-delta"><p class="eyebrow">Le déplacement observé</p><div class="result-line"><span>${money(prev.stats.min_reallocation_cad)} CAD</span><b aria-hidden="true">→</b><strong>${money(s.v.stats.min_reallocation_cad)} CAD</strong></div>${delta(s)}</section>`:''}`}
function deep(s){const p=s.v.problem;return `<section class="deep-intro"><p class="eyebrow">Voir au-delà · lecture méthodologique</p><h1>Le calcul,<br><span>en pleine lumière.</span></h1><div class="deep-facts"><span>Minimum conditionnel <strong>${money(s.v.stats.min_reallocation_cad)} CAD</strong></span><span>Réserve demandée <strong>${money(p.withdrawal_cad)} CAD</strong></span><span>Source <strong>${s.local?'Calcul local · copie':esc(s.v.source?.analysis_ref||'référence absente')}</strong></span></div></section>${s.previous?`<section class="compare-delta"><h2>Écart avec l’état précédent.</h2>${delta(s)}</section>`:''}<div class="method-layout"><aside class="method-rail"><span class="eyebrow">Une chaîne inspectable</span><ol><li>Question financière</li><li>Hypothèses déclarées</li><li>Calcul déterministe</li><li>Contrôles et limites</li></ol>${action('Les documents consultés','proof','data-proof="sources"','text-action')}${action('Le travail des quatre agents','proof','data-proof="agents"','text-action')}</aside><section class="method-surface">${methodDetails(s)}</section></div><section class="deep-comparison"><div class="section-heading"><h2>Les sorties, dans les mêmes unités.</h2>${action('Examiner le minimum','proof','data-proof="minimum_reallocation"','text-action')}</div><div class="table-scroll"><table><caption>Résultats conditionnels en CAD. Aucune probabilité associée aux chocs.</caption><thead><tr><th>Option</th><th>Capital déplacé</th><th>Perte · actions</th><th>Perte · obligations</th><th>Statut</th></tr></thead><tbody>${options(s).map(o=>`<tr><th>${esc(o.label)}</th><td>${money(o.turnover)}</td><td>${loss(o,'actions')}</td><td>${loss(o,'obligations')}</td><td>${badge(o)}</td></tr>`).join('')}</tbody></table></div></section>`}
function render(s){return `${header(s)}<div class="shell">${nav(s)}${s.notice?`<div class="notice" role="status">${esc(s.notice)}</div>`:''}${s.error?`<div class="error-note" role="alert">${esc(typeof s.error==='string'?s.error:s.error.message||JSON.stringify(s.error))}</div>`:''}${s.view==='revise'?revise(s):!options(s).length||s.v.stats.min_reallocation_cad==null?unresolved(s):s.view==='compare'?(s.level==='deep'?deep(s):compare(s)):s.level==='deep'?deep(s):overview(s)}<section class="scope"><div class="scope-mark" aria-hidden="true">↳</div><div><h2>Le cadre reste visible.</h2>${limits(s)}</div></section><section class="evidence-strip"><span>La lumière attire le regard.<br><strong>Les preuves soutiennent la conclusion.</strong></span><div>${action('Sources','proof','data-proof="sources"','text-action')}${action('Calcul','proof','data-proof="method"','text-action')}${action('Agents','proof','data-proof="agents"','text-action')}</div></section></div><footer><span>AlphaForge · direction Prisme</span><span>Dossier fictif · calculs traçables · aucune garantie de placement</span><a href="../index.html">Retour aux directions ↗</a></footer>`}
mount(render,{name:'Prisme'});
